# tests/conftest.py from sqlalchemy.orm import Session
@pytest.fixture(name="db_session") def db_session_fixture(tmp_path) -> Generator[Session, None, None]: """Per-test SQLite session against a fresh, empty database."""
# Function-scoped. Every test gets its own SQLite file under pytest's tmp_path, so no test # can see rows another test wrote. # # Schema: links, tags and link_tags, all created by Base.metadata.create_all. # Foreign keys ARE enforced (app/db.py's Engine-class PRAGMA listener applies). # expire_on_commit=False, matching app/db.py's SessionLocal, so attributes stay readable # after commit. # # Usage: # def test_something(db_session: Session): # db_session.add(Link(url="https://example.com/a", title="A", # created_at=datetime(2026, 1, 1, 12, 0, 0))) # db_session.commit() # # created_at is naive (tzinfo None) - pass naive datetimes.

# tests/conftest.py from fastapi.testclient import TestClient
@pytest.fixture(name="client") def client_fixture(db_session: Session) -> Generator[TestClient, None, None]: """TestClient for app.main:app, with get_db overridden to use db_session, so tests never touch the real database file. Shares the db_session transaction, so rows added via db_session are visible to requests."""
# Depends on db_session, so requesting `client` alone still gets an isolated database. # Request BOTH when a test needs to seed rows and then call the API: # def test_listing(client: TestClient, db_session: Session): # db_session.add(Link(url="https://example.com/a")); db_session.commit() # assert client.get("/links").status_code == 200 # # The override is installed as app.dependency_overrides[get_db] and REMOVED in a finally # block on teardown, so it never leaks into the next test. # # A test may install its own temporary override on top - tests/test_list_links.py does # exactly this to exercise the read-failure branch of list-links#4: # fastapi_app.dependency_overrides[get_db] = lambda: _FailingSession() # ... # fastapi_app.dependency_overrides.pop(get_db, None) # The fixture uses .pop() rather than .clear() precisely so that pattern keeps working.
